257	        btn.classList.add('dialogue-btn-active');
258	        btn.setAttribute('aria-expanded', 'true');
259	
260	        var dlgSlug = btn.getAttribute('data-slug');
261	        var dlgFilename = btn.getAttribute('data-filename');
